  "claim": {
    "component_id": "C035",
    "value": "A targeted mitigation should expand only when reliable discriminating evidence favors its mechanism and the canary meets the predefined bounds.",
    "scope": "Joint necessary conditions; the bounds cover instrumentation overhead, error rate, completion rate and tail delay against comparable baseline traffic.",
